class Solution:
    def distinctDifferenceArray(self, nums: List[int]) -> List[int]:
        pre = Counter(nums[:])
        suf = Counter(nums)
        res = []
        for i in range(len(nums)):
            res.append(len(pre) - len(suf))
            suf[nums[i]] -= 1
            if suf[nums[i]] == 0:
